import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,P as o,q as n}from"./D3cAVrQp.js";const r={title:"Governance Method, Experiment, Adoption, and Implementation Authority Interface Specification",version:"0.2.1",specification_id:"GMEAIA/0.2.1",status:"coherence-patched-draft-successor",date:"2026-08-05T00:00:00.000Z",constitutional_interface:"Constitutional Interface Specification v0.2.1"},{title:l,version:p,specification_id:u,status:g,date:h,constitutional_interface:m}=r;var a=i('<h1>Governance Method, Experiment, Adoption, and Implementation Authority Interface Specification v0.2.1</h1> <h2>A shared lifecycle grammar for methods, experiments, authority, response, implementation, learning, and closure</h2> <p><strong>Specification ID:</strong> <code>GMEAIA/0.2.1</code><br> <strong>Status:</strong> Coherence-patched draft successor to <code>GMEAIA/0.1</code> for adversarial review and stack migration<br> <strong>Legal character:</strong> Record, interoperability, and lifecycle specification; not a source of jurisdiction, consent, public office, funding, emergency command, adjudication, or coercive authority<br> <strong>Constitutional dependency:</strong> Constitutional Interface Specification v0.2.1<br> <strong>Compatibility:</strong> Preserves v0.1 identifiers and common-header fields; semantic migration and regenerated machine-readable companions are required before adoption</p> <blockquote><p><strong>Methods structure how authority is exercised. They do not create the authority.</strong></p> <p><strong>Retained jurisdiction does not excuse unrecorded omission. Conformance does not establish success.</strong></p></blockquote> <h2>Version history</h2> <ul><li><strong>0.2.1 (2026-08-05):</strong> Coherence patch. Renamed consequence profiles to <code>CP0</code>–<code>CP3</code>; separated capacity limitation from constitutional absence; normalized handoff states; made response-duty and clock sources explicit; adopted core-plus-trigger proportional profiles; restored normative language, source lineage, migration status, and the protected-domain catalogue; typed jointly constituted authority; clarified framework-falsification scope; and made GMEAIA the sole operational source for response fields and lifecycle states.</li> <li><strong>0.2 (2026-08-05):</strong> Recursive systems-audit successor. Integrated causal responsibility, response/refusal/omission states, constitutional-gap handling, common-mode dependence, objective-reproduction review, consequence-scaled record profiles, administrative-burden limits, causally adequate pilots, support-withdrawal durability, compatibility-power review, and framework-level falsification. No new record IDs or universal header fields were added.</li> <li><strong>0.1 (2026-08-02):</strong> First reconciled specification, assembled from the sixty record classes already asserted by EGP, IAF, IMT, IRF, and WDIP companions. Established authority-effect labels, protected domains, fail-closed lifecycle states, recipient acceptance, correction, remedy, closure, and the forty-eight-field common header.</li></ul> <h2>Normative language</h2> <ul><li><strong>SHALL / MUST</strong> indicates a required conformance condition.</li> <li><strong>SHALL NOT / MUST NOT</strong> indicates a prohibited condition.</li> <li><strong>SHOULD</strong> indicates a strong presumption that may be departed from only with recorded reasons.</li> <li><strong>MAY</strong> indicates a permitted option.</li></ul> <h2>Source lineage and dependency freeze</h2> <table><thead><tr><th>Source or dependency</th><th>File</th><th>SHA-256 or status</th></tr></thead><tbody><tr><td>Immediate draft predecessor</td><td><code>governance-method-experiment-adoption-implementation-authority-interface-specification-v0.2.md</code></td><td><code>d16969e55d32214e605b1c0b273675f9f0b84dcee462604c2e626b477504e947</code></td></tr><tr><td>Normative lineage source</td><td><code>governance-method-experiment-adoption-implementation-authority-interface-specification-v0.1.md</code></td><td><code>1f2ed4646e552373c15a6a5bc57e0b5f03a30dff84579d293316b9deb3c96b79</code></td></tr><tr><td>Constitutional dependency</td><td><code>constitutional-interface-specification-v0.2.1.md</code></td><td><code>2ab06be70d568be82efde2ccbcc3f8df48f37308fab3ccf116ac3efe4c167bfc</code></td></tr><tr><td>Emergency interface</td><td><code>emergency-catastrophic-risk-continuity-interface-specification-v0.1.md</code></td><td><code>c673742b1317c7169d4b8226118478c990e9a3d05084b2dc5ac9ad2f1971163c</code></td></tr><tr><td>Security and coercion interface</td><td><code>security-coercion-protective-action-interface-specification-v0.1.md</code></td><td><code>b8f1dd0f676044542a23184f52200e50b106a798545c7c57119ded2c439b6299</code></td></tr><tr><td>Commons, ecological rights, guardianship, title, and resource interface</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td><code>3c45e37c834c727471657fc91149edbe3011137562c2dd73e54b20226c92589b</code></td></tr><tr><td>Cross-domain emergency transport</td><td><code>CDEE/0.1</code></td><td>exact dependency remains governed by the adopting release registry</td></tr><tr><td>Audit synthesis</td><td><em>Cross-Framework Systems Audit Synthesis v0.1</em></td><td>working source; checksum not yet frozen</td></tr></tbody></table> <h2>Migration status</h2> <p><code>GMEAIA/0.2.1</code> preserves v0.1 record identifiers, action classes, authority-effect labels, and the forty-eight-field common header. It is <strong>identifier-compatible but semantically migration-requiring</strong>. Existing v0.1 JSON, JSON Schema, examples, validation outputs, manifests, and <code>IAEG-CLUSTER/0.1</code> registries remain pinned to <code>GMEAIA/0.1</code> until regenerated, tested, and separately adopted for v0.2.1.</p> <hr> <h1>1. Purpose, scope, and constitutional position</h1> <p><code>GMEAIA/0.2.1</code> supplies a common type system for governance records that move from signal to proposal, consent, authority, activation, implementation, review, scaling, remedy, and closure.</p> <p>It exists to prevent recurring category errors:</p> <ul><li>an observation becoming a finding;</li> <li>a method becoming a mandate;</li> <li>an adoption claim becoming activation;</li> <li>funding becoming permission;</li> <li>a metric becoming judgment;</li> <li>a pilot becoming jurisdiction;</li> <li>a handoff becoming silent responsibility transfer;</li> <li>a valid authority retaining jurisdiction while its delay or refusal disappears;</li> <li>conformance becoming evidence of effectiveness.</li></ul> <p>The specification does not decide substantive questions. It records the authority, evidence, responsibility, clocks, limits, and lifecycle states through which a competent institution decides them.</p> <h2>1.1 What v0.2 changes</h2> <p>The v0.1 architecture already separated method from authority. The comparative audit showed four additional shared needs:</p> <ol><li><strong>Causal responsibility:</strong> identify who controls the variables generating the condition, not only who administers its consequences.</li> <li><strong>Response and omission:</strong> record acceptance, refusal, delay, timeout, escalation, and constitutional gaps without automatic transfer of jurisdiction.</li> <li><strong>Independence and objective reproduction:</strong> test common-mode dependencies and the incentives that cause institutional behavior to return after reform.</li> <li><strong>Proportionality and falsification:</strong> match record depth to consequence and require frameworks to risk their own narrowing or replacement.</li></ol> <p>These functions are integrated into existing records rather than added as new classes.</p> <h2>1.2 Non-authority and non-certification</h2> <p>Schema validation, cryptographic proof, exact versioning, complete records, software capability, successful tests, conformance certification, or inclusion in a GGF registry does not establish lawful authority, factual accuracy, legitimate representation, consent, effectiveness, or justice.</p> <hr> <h1>2. Definitions</h1> <p><strong>activation.</strong> The distinct act that starts an already authorized action and begins operational, review, response, and expiry clocks.</p> <p><strong>adoption claim.</strong> A statement that an entity has accepted or intends to implement a proposal; its effect depends on separately recorded authority.</p> <p><strong>administrative capacity.</strong> The ability to administer a process, service, or mitigation. It is not necessarily control over the condition’s causes.</p> <p><strong>authority envelope.</strong> Linked records establishing consent, authority, jurisdiction, causal responsibility, scope, protected rights, trial conditions, activation, review, exit, remedy, and closure.</p> <p><strong>causal control.</strong> Legal or practical capacity to alter a variable materially contributing to the condition at issue.</p> <p><strong>capacity gap.</strong> A condition in which an authority possesses relevant jurisdiction or duty but lacks sufficient practical capacity, resources, infrastructure, or access to discharge it fully.</p> <p><strong>causally adequate pilot.</strong> A pilot no larger than necessary for safety and no smaller than necessary to expose the mechanism it claims to test.</p> <p><strong>common-mode dependency.</strong> A shared data, model, AI, funder, platform, infrastructure, method, appointment authority, professional network, or ontology capable of biasing or disabling several nominally distinct channels at once.</p> <p><strong>consequence profile.</strong> A <code>CP0</code>–<code>CP3</code> proportional record profile selected according to reversibility, rights, coercion, service effects, affected outsiders, ecological irreversibility, data sensitivity, duration, and scale.</p> <p><strong>constitutional gap.</strong> A consequential condition for which no identified authority possesses sufficient lawful jurisdiction. Practical incapacity within an otherwise valid jurisdiction is a capacity gap, not a constitutional gap.</p> <p><strong>consequential action.</strong> An action capable of materially affecting rights, duties, services, money, assets, status, safety, public institutions, protected knowledge, ecosystems, or nonparticipants.</p> <p><strong>objective reproduction.</strong> The budget, appointment, promotion, discipline, prestige, blame, survival, professional, and continuation pressures likely to regenerate characteristic institutional behavior.</p> <p><strong>omission.</strong> A consequential failure to accept, refuse, defer, refer, or act within a defined responsibility and response clock. The term does not by itself establish illegality or liability.</p> <p><strong>protected domain.</strong> A domain in which ordinary experimentation is insufficient and a specialized authority interface is required.</p> <h2>2.1 Protected-domain catalogue</h2> <p>Ordinary trial authorization cannot by itself cover:</p> <ul><li>detention, policing, search, seizure, restraint, force, or sanctions;</li> <li>borders, migration status, deportation, asylum, or movement restrictions;</li> <li>withdrawal or material restriction of essential services;</li> <li>taxation, forfeiture, compulsory levies, or benefit withdrawal;</li> <li>title, tenure, land, housing, guardianship, or custody transfer;</li> <li>child protection, child guardianship, or decisions materially affecting children’s legal status;</li> <li>irreversible or high-risk ecological intervention;</li> <li>high-risk technology, critical infrastructure, or safety-critical automation;</li> <li>adjudication, binding findings of guilt, liability, or legal status;</li> <li>emergency declaration, command, requisition, or extraordinary powers.</li></ul> <p>The catalogue is non-exhaustive where a controlling constitutional or domain interface identifies additional protected matters. <code>GMEAIA-56</code> and <code>GMEAIA-57</code> route such actions; they do not supply the underlying authority.</p> <p><strong>response clock.</strong> A decision-appropriate deadline for acknowledgment, acceptance, refusal, referral, action, review, or escalation.</p> <p><strong>retained jurisdiction.</strong> Authority that remains with an institution despite coordination, review, or referral. It may carry a separately constituted duty to respond.</p> <hr> <h1>3. Constitutional doctrines</h1> <h2>3.1 Method–authority separation</h2> <p>Methods, tools, facilitation, ethics review, cultural adaptation, AI, scores, dashboards, funding, signatures, and technical capabilities cannot create powers their users do not independently possess.</p> <h2>3.2 Decision-chain separation</h2> <p>Observation, validation, proposal, consent, authorization, activation, execution, evaluation, adjudication, remedy, and closure remain distinct records and effects.</p> <h2>3.3 Causal responsibility</h2> <p>Responsibility allocation should follow lawful jurisdiction, causal control, practical capacity, and accompanying resources. Affected-party standing determines participation, evidence, consent where applicable, challenge, and remedy; it does not itself assign responsibility. The location where consequences appear does not alone determine responsibility.</p> <h2>3.4 Duty attached to retained jurisdiction</h2> <p>Every consequential referral shall disclose whether a response duty exists, its source, and its effect. Where law, treaty, charter, compact, contract, valid internal rule, or voluntary commitment establishes that duty, the competent authority shall acknowledge and accept, refuse, defer, or refer the request within a decision-appropriate period. Delay does not create authority transfer, but it does not erase responsibility for avoidable non-action.</p> <h2>3.5 Constitutional gaps</h2> <p>If no competent authority exists, the record state is <code>constitutional_gap</code>. The matter is routed toward a lawful constituting process. The interface does not fill the gap itself.</p> <h2>3.6 Proportionality</h2> <p>Record depth scales with consequence. Low-risk voluntary activity shall not require closure-grade process. High-risk action cannot avoid safeguards because it is technically simple or popular.</p> <h2>3.7 Conformance is not success</h2> <p>A valid record proves only that required distinctions were represented. Independent outcomes, causal assessment, and affected-party evidence determine whether the action worked.</p> <h2>3.8 No automatic consequence from metrics</h2> <p>Indicators may trigger inquiry, review, or a pre-authorized reversible safe state. They do not independently activate, fund, scale, punish, transfer authority, dissolve institutions, or renew power.</p> <h2>3.9 Protected continuity and unresolved duties</h2> <p>Expiry ends temporary power, not wages, debts, pensions, rights, remedies, records duties, essential services, restoration, or unresolved claims.</p> <h2>3.10 Framework-level falsification</h2> <p>Every operational framework or tool core shall state its theory of change, disconfirming evidence, and conditions for narrowing, suspension, replacement, deprecation, or non-scaling.</p> <hr> <h1>4. Action classes</h1> <ul><li><strong><code>A01</code> — Sense and observation:</strong> Signals, observations, complaints, opportunities, alerts, and preliminary claims.</li> <li><strong><code>A02</code> — Validation and jurisdictional triage:</strong> Provenance checks, uncertainty, severity, response clocks, routing, referral, and omission states.</li> <li><strong><code>A03</code> — Proposal and alternative formation:</strong> Candidate responses, causal mechanisms, alternatives, reversibility, resources, and expected effects.</li> <li><strong><code>A04</code> — Method selection and deliberation:</strong> Choice and adaptation of deliberative, epistemic, ethical, cultural, technical, or facilitation methods.</li> <li><strong><code>A05</code> — Affected-party authority, consent, refusal, and representation:</strong> Who is affected, who may decide, who must consent, who may refuse, and who may represent whom.</li> <li><strong><code>A06</code> — Authority verification and protected-domain classification:</strong> Legal source, causal responsibility, jurisdiction, exact power, limits, activation state, and specialized routes.</li> <li><strong><code>A07</code> — Trial authorization and adoption registration:</strong> Lawful permission for bounded trials and registration of adoption claims.</li> <li><strong><code>A08</code> — Operational activation and implementation:</strong> The distinct act that begins operations, assigns operators, releases resources, and starts clocks.</li> <li><strong><code>A09</code> — Monitoring, evidence, review, and challenge:</strong> Baselines, metrics, observations, causal assessment, complaints, interim relief, and corrections.</li> <li><strong><code>A10</code> — Amendment, pause, renewal, rollback, and scaling:</strong> Change control without silent expansion, including transition readiness and new-jurisdiction authorization.</li> <li><strong><code>A11</code> — Expiry, termination, closure, remedy, and authority return:</strong> Ending power, restoring arrangements, preserving duties, disposing data, and compensating harm.</li> <li><strong><code>A12</code> — Readiness, ethics, epistemic, and institutional assessment:</strong> Advisory assessments exposing risk, common-mode dependence, and missing conditions without hidden vetoes.</li> <li><strong><code>A13</code> — Facilitators, auditors, catalyst teams, and technical services:</strong> Qualifications, mandates, conflicts, incentives, complaints, liability, and non-monopoly rules.</li> <li><strong><code>A14</code> — Funding, procurement, participation support, and incentives:</strong> Financial authority, independent support, contracts, continuation incentives, essential continuity, and appeals.</li> <li><strong><code>A15</code> — Institutional regeneration, charter change, and dissolution:</strong> Mandate, objective reproduction, governance redesign, continuity, succession, and unresolved duties.</li> <li><strong><code>A16</code> — Data, identity, automation, publication, archives, and tool stewardship:</strong> Protected data, AI limits, versioning, compatibility power, forks, learning libraries, and deletion.</li> <li><strong><code>A17</code> — Emergency, urgent, protected-domain, and coercive handoffs:</strong> CDEE/ECRC referrals, protected-domain exceptions, SCPA execution, and domain-specific interfaces.</li> <li><strong><code>A18</code> — Non-activation, conformance, proportionality, and interoperability:</strong> Fail-closed pilots, authority-effect labels, consequence profiles, handoff acceptance, compatibility, and release controls.</li></ul> <hr> <h1>5. Authority-effect, normative-force, and handoff states</h1> <h2>5.1 Authority-effect labels</h2> <table><thead><tr><th>Label</th><th>Meaning</th></tr></thead><tbody><tr><td><code>none</code></td><td>Educational, expressive, simulated, or descriptive; creates no procedural or legal effect.</td></tr><tr><td><code>advisory</code></td><td>Offers analysis or recommendations; a response duty exists only where a valid rule or charter establishes it.</td></tr><tr><td><code>procedural_support</code></td><td>Structures participation or records a process; does not decide the substantive issue.</td></tr><tr><td><code>evidentiary</code></td><td>May be considered as evidence for a stated purpose; does not establish liability, consent, or authority.</td></tr><tr><td><code>consent_evidence</code></td><td>Records a valid holder’s decision within its exact scope; does not create jurisdiction or waive others’ rights.</td></tr><tr><td><code>authority_reference</code></td><td>Points to an independently valid authority record; does not itself grant power.</td></tr><tr><td><code>authorizing</code></td><td>A decision by a competent authority under an exact legal source.</td></tr><tr><td><code>activating</code></td><td>Starts an already authorized action and its clocks.</td></tr><tr><td><code>executing</code></td><td>Carries out a separately authorized operation within defined limits.</td></tr><tr><td><code>closing</code></td><td>Terminates power, returns authority and assets, disposes data, and preserves unresolved duties.</td></tr></tbody></table> <h2>5.2 Normative-force and lifecycle states</h2> <p>Records shall distinguish at minimum:</p> <p><code>draft</code>, <code>asserted</code>, <code>received</code>, <code>validated_for_purpose</code>, <code>referred</code>, <code>proposed</code>, <code>under_deliberation</code>, <code>consent_pending</code>, <code>authority_pending</code>, <code>authorized</code>, <code>registered</code>, <code>activated</code>, <code>paused</code>, <code>suspended</code>, <code>expired</code>, <code>terminated</code>, <code>closed</code>, <code>corrected</code>, <code>superseded</code>, <code>rejected</code>, <code>unresolved</code>, and <code>non_activated</code>.</p> <h2>5.3 Handoff states</h2> <p>Consequential handoffs additionally distinguish the exact controlled values:</p> <p><code>offered</code>, <code>acknowledged</code>, <code>accepted</code>, <code>partially_accepted</code>, <code>capacity_limited</code>, <code>refused</code>, <code>deferred</code>, <code>referred</code>, <code>timed_out</code>, <code>misrouted</code>, <code>constitutional_gap</code>, <code>returned</code>, and <code>closed</code>.</p> <p><code>capacity_limited</code> means that the recipient recognizes relevant jurisdiction or duty but cannot presently discharge it fully. <code>constitutional_gap</code> means that no identified authority possesses sufficient lawful jurisdiction. Deliberate obstruction is a reviewed finding, not a raw transport state.</p> <p>Silence is not acceptance. A timeout is not a substantive finding. A recipient’s refusal does not by itself discharge the sender’s continuing duties.</p> <h2>5.4 Fail-closed state</h2> <p>A consequential action remains <code>authority_pending</code> or <code>non_activated</code> when required authority, consent, protected-domain, activation, review, response, or remedy records are missing, expired, suspended, rejected, or unresolved beyond the permitted threshold.</p> <p>Fail-closed behavior shall be proportionate. Missing fields for a low-risk non-consequential activity do not justify treating the activity as a protected-domain intervention.</p> <hr> <h1>6. Common record architecture</h1> <h2>6.1 Forty-eight-field header retained</h2> <p>v0.2 does not enlarge the universal header. New audit functions live in record-specific content and linked profiles. This avoids imposing every possible field on every record.</p> <h2>6.2 Public and protected layers</h2> <p>Public metadata identifies the action, authority effect, status, general reasons, duration, response clocks, challenge, and closure. Protected annexes preserve personal, Indigenous, security, health, whistleblower, commercial, and legally sealed material.</p> <h2>6.3 Dependency graph and correction propagation</h2> <p>Systems preserve explicit links among source signals, proposals, consent, authority, causal responsibility, activation, implementation, review, handoffs, correction, remedy, and closure. A correction propagates to every dependent record.</p> <h2>6.4 Human accountability</h2> <p>Every consequential automated, organizational, or collective record names a human accountable officer or lawfully constituted body with a reachable complaint route.</p> <h2>6.5 Record reuse and administrative burden</h2> <p>A valid existing record may satisfy several profiles where its purpose, authority, scope, status, access, and lifecycle remain clear. Systems shall report estimated preparation, translation, legal, technical, participation, maintenance, and audit burden and who bears it.</p> <h2>6.6 Consequence-scaled profiles</h2> <p>The profile records required semantic functions, not necessarily separate forms. Valid records may be combined or reused where their authority, purpose, scope, access, status, challenge, and closure semantics remain clear.</p> <h3><code>CP0</code> — Exploratory and non-consequential</h3> <p>Examples: public education, optional brainstorming, non-operative drafting, simulation, or demonstration.</p> <p><strong>Core:</strong> one compact non-operative record identifying the method or artifact, responsible actor, authority effect, and non-activation status. Data and closure semantics are added where material.</p> <p><code>GMEAIA-58</code> is required only for an actual sandbox, prototype, simulation, demonstration, or non-production deployment—not for every educational or exploratory conversation.</p> <h3><code>CP1</code> — Voluntary bounded practice</h3> <p>Affects consenting participants within existing authority, without material effect on non-participants, essential services, employment, public funds, or protected domains.</p> <p><strong>Core semantic functions:</strong> actor and method; voluntary scope; consent, refusal, and withdrawal; implementation responsibility; stop and expiry; complaint and correction route.</p> <p>Affected-party, accessibility, funding, vendor, data, AI, learning, and data-disposition records are added only when those functions are materially present.</p> <h3><code>CP2</code> — Operational or consequential action</h3> <p>May affect workload, services, public resources, institutional operations, affected outsiders, or material rights.</p> <p><strong>Core semantic functions:</strong> constituting authority; affected parties; causal responsibility; authorization and activation; implementation ownership and dependencies; monitoring and review; challenge and remedy; closure and unresolved-duty custody.</p> <p>Funding, procurement, AI, data, cross-framework handoff, institutional transition, and other records are added only when triggered by the action.</p> <h3><code>CP3</code> — Protected-domain or constitutional action</h3> <p><code>CP2</code> plus <code>GMEAIA-56</code> or <code>GMEAIA-57</code> and the controlling specialized interface. Ordinary GMEAIA conformance is never sufficient by itself.</p> <h3>Profile location</h3> <p>Because the common header remains stable, the selected consequence profile shall be recorded in the relevant record-specific content:</p> <ul><li><code>GMEAIA-02</code> for a method, tool, protocol, or template;</li> <li><code>GMEAIA-07</code> for an incoming condition and its response-time assessment;</li> <li><code>GMEAIA-20</code> for a consequential action or authority decision;</li> <li><code>GMEAIA-58</code> for a sandbox, prototype, simulation, or demonstration.</li></ul> <h2>6.7 Framework falsification profile</h2> <p>Framework-level review is carried primarily by <code>GMEAIA-53</code>, supported by <code>30</code>, <code>32</code>, <code>43</code>, and <code>45</code>. It applies to frameworks and to long-lived, systemically central, or self-renewing mechanisms—not to every local action. It shall state:</p> <ul><li>central theory of change;</li> <li>expected mechanism;</li> <li>disconfirming evidence;</li> <li>architecture-added latency and burden;</li> <li>dependency and common-mode risk;</li> <li>narrowing, suspension, replacement, and non-scaling conditions.</li></ul> <hr> <h1>7. Lifecycle rules</h1> <h2>7.1 Sensing and validation</h2> <p>Anyone permitted by the receiving system may submit a signal. The signal begins as an assertion. Validation is purpose-specific and does not establish jurisdiction, guilt, emergency status, or liability.</p> <h2>7.2 Routing, response, and omission</h2> <p>A validated matter may be referred to a candidate authority. The referral records the response-duty source and effect; acknowledgment and decision clocks; acceptance, refusal, capacity limitation, deferment, onward referral, or timeout; reasons, conflicts, expected harm during delay, sender and recipient duties, escalation, and jurisdictional status.</p> <p>A consequential response clock shall cite a valid legal, treaty, charter, compact, contract, internal-rule, or voluntary-commitment deadline, a <code>GMEAIA-07</code> response-time assessment, or both. Where the lawful deadline exceeds the maximum tolerable delay, the record identifies interim protection and escalation without treating urgency as new jurisdiction.</p> <p>Acceptance closes neither the action clock nor the omission question. Accepted responsibility remains linked to implementation, review, and performance clocks so that post-acceptance non-action remains visible.</p> <h2>7.3 Proposal and causal adequacy</h2> <p>A proposal identifies alternatives, rights effects, causal mechanism, controlled and uncontrolled variables, minimum causally adequate scope, and what the proposed action cannot establish.</p> <h2>7.4 Consent and authority</h2> <p>Consent, public-law authority, affected-nation authority, worker decisions, and participation remain distinct. Authority verification includes causal responsibility and protected-domain classification.</p> <h2>7.5 Authorization, adoption, and activation</h2> <p>A trial authorization permits a bounded action. Adoption records acceptance. Activation starts the action and its clocks. None substitutes for the others.</p> <h2>7.6 Implementation and handoffs</h2> <p>Implementation plans assign owners, handoff clocks, service boundaries, ordinary maintenance, and support-withdrawal durability. A failed handoff retains named custody.</p> <h2>7.7 Monitoring, correction, and remedy</h2> <p>Monitoring includes outcomes, distribution, latency, administrative burden, and common-mode failures. Thresholds trigger review, not automatic consequence. Harm and erroneous records remain remediable after termination.</p> <h2>7.8 Scaling and institutionalization</h2> <p>Scaling evidence states causal adequacy, contexts not tested, ordinary owner, budget, staffing, maintenance, and durability after exceptional support ends. Scaling and permanent enactment require new authority.</p> <h2>7.9 Expiry and closure</h2> <p>Temporary power expires. Continuing duties persist. Closure returns authority, assets, records, access, and unresolved duties to lawful custodians.</p> <hr> <h1>8. Canonical record catalogue</h1> <p>All sixty v0.1 identifiers are retained. Titles changed only where necessary to make the audit additions visible; downstream profiles may continue to use the original IDs during migration.</p> <h2>GMEAIA-01 — Constituting Instrument, Legal Source, Jurisdiction, and Activation Status</h2> <p><strong>Action class:</strong> <code>A06</code><br> <strong>Purpose:</strong> Identifies the presently valid source of authority for a consequential governance action.</p> <p><strong>Required content:</strong></p> <ul><li>constituting instrument and exact section;</li> <li>competent authority and office holder or body;</li> <li>territorial, personal, subject-matter, and temporal jurisdiction;</li> <li>exact power and prohibited uses;</li> <li>authority formation: <code>retained</code>, <code>delegated</code>, <code>transferred</code>, <code>concurrent</code>, <code>jointly_constituted</code>, or <code>absent</code>;</li> <li>for <code>jointly_constituted</code>: constituting parties, shared governance object, affected non-parties, compact or legal source, exit, and surviving duties;</li> <li>activation, ratification, delegation, and suspension status;</li> <li>review, expiry, amendment, and revocation route;</li> <li>conflicts with other law or authority;</li> <li>public reasons and protected annex;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A framework reference, policy goal, software token, vote, consensus, urgency, funding condition, or pilot success cannot substitute for this record.</li></ul> <p><strong>Lifecycle relation:</strong> Required before trial authorization, activation, institutional change, funding condition, emergency action, or coercive handoff.</p> <h2>GMEAIA-02 — Method, Tool, Protocol, Template, and Authority-Effect Classification</h2> <p><strong>Action class:</strong> <code>A18</code><br> <strong>Purpose:</strong> Classifies an implementation instrument by what it can and cannot legally do.</p> <p><strong>Required content:</strong></p> <ul><li>tool or method identity and version;</li> <li>steward and authoritative source;</li> <li>intended purpose and users;</li> <li>authority-effect label;</li> <li>domains and contexts;</li> <li>required dependencies;</li> <li>known limitations and failure modes;</li> <li>deprecation and correction route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A template does not create a council, office, court, consent, charter, benefit, emergency power, or enforcement authority.</li></ul> <p><strong>Lifecycle relation:</strong> Must accompany every tool stack, resource card, method recommendation, and software module.</p> <h2>GMEAIA-03 — Actor, Agent, Office, Representation, and Technical Capability Record</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Distinguishes identity, technical access, organizational role, public office, representation, and fiduciary standing.</p> <p><strong>Required content:</strong></p> <ul><li>actor identity and type;</li> <li>human, body, community, organization, AI, sensor, or service role;</li> <li>office or mandate source;</li> <li>representation constituency and selection;</li> <li>technical credentials and capability tokens;</li> <li>conflicts and recusal;</li> <li>contact and accountability route;</li> <li>expiry and succession;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A DID, UCAN, API key, signature, organizational title, community label, or facilitator certificate does not establish public office or authority to represent others.</li></ul> <p><strong>Lifecycle relation:</strong> Links every action to a responsible actor and separately valid authority.</p> <h2>GMEAIA-04 — Sense Signal, Complaint, Opportunity, and Asserted Scope Record</h2> <p><strong>Action class:</strong> <code>A01</code><br> <strong>Purpose:</strong> Preserves what an agent reports without treating the report as verified fact.</p> <p><strong>Required content:</strong></p> <ul><li>signal identity and timestamp;</li> <li>reporting agent;</li> <li>plain-language claim;</li> <li>claimed location and scope;</li> <li>claimed affected parties;</li> <li>claimed severity and urgency;</li> <li>submitted evidence and source restrictions;</li> <li>requested response or no-response preference;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Severity, urgency, jurisdiction, causation, affected-party identity, and legal violation remain asserted until separately validated.</li></ul> <p><strong>Lifecycle relation:</strong> May be created by any permitted agent; cannot directly activate a consequential action.</p> <h2>GMEAIA-05 — Observation, Evidence, Provenance, and Protected-Source Record</h2> <p><strong>Action class:</strong> <code>A01</code><br> <strong>Purpose:</strong> Records observations and supporting material with provenance, uncertainty, consent, and access controls.</p> <p><strong>Required content:</strong></p> <ul><li>observation method and instrument;</li> <li>time, place, sampling, and chain;</li> <li>source identity or protected-source class;</li> <li>data quality and uncertainty;</li> <li>consent and lawful basis;</li> <li>access, retention, and use restrictions;</li> <li>correction and contest status;</li> <li>hashes or locators without exposing protected payloads;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Cryptographic integrity proves that bytes are unchanged, not that the observation is true, lawful, representative, or admissible.</li></ul> <p><strong>Lifecycle relation:</strong> Supports validation, assessment, investigation, or monitoring.</p> <h2>GMEAIA-06 — Signal Validation, Corroboration, and Status Record</h2> <p><strong>Action class:</strong> <code>A02</code><br> <strong>Purpose:</strong> Classifies a signal as unreviewed, partially corroborated, validated for a stated purpose, disputed, false, or unresolved.</p> <p><strong>Required content:</strong></p> <ul><li>validation authority and competence;</li> <li>methods and sources;</li> <li>independence and conflicts;</li> <li>claims tested and not tested;</li> <li>corroboration and contradiction;</li> <li>uncertainty and minority views;</li> <li>status and permitted downstream uses;</li> <li>recheck, correction, and expiry;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Validation for routing does not establish legal breach, emergency, liability, or authority to act.</li></ul> <p><strong>Lifecycle relation:</strong> Required before consequential routing that relies on severity, urgency, or identity.</p> <h2>GMEAIA-07 — Severity, Urgency, Reversibility, Uncertainty, and Response-Time Assessment</h2> <p><strong>Action class:</strong> <code>A02</code><br> <strong>Purpose:</strong> Separates seriousness and time sensitivity from authority while determining whether the complete response loop is compatible with the condition.</p> <p><strong>Required content:</strong></p> <ul><li>harm dimensions and exposed populations;</li> <li>disturbance timescale and rate of change;</li> <li>reversibility, lock-in, and irreversibility horizon;</li> <li>confidence, uncertainty, and alternative explanations;</li> <li>distributional effects;</li> <li>least-harmful delay and action options;</li> <li>maximum tolerable sensing, decision, and action delay;</li> <li>coordination-added latency and review clock;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>High severity, urgency, or a missed clock cannot create jurisdiction, emergency status, coercive power, or automatic authority transfer.</li></ul> <p><strong>Lifecycle relation:</strong> Informs routing, proportional clocks, precautionary recommendations, and omission review.</p> <h2>GMEAIA-08 — Jurisdictional Triage, Competent-Authority Referral, Response, and Acceptance</h2> <p><strong>Action class:</strong> <code>A02</code><br> <strong>Purpose:</strong> Routes a validated matter without transferring power by silence and makes acceptance, refusal, delay, and constitutional gaps visible.</p> <p><strong>Required content:</strong></p> <ul><li>referring actor and source record;</li> <li>candidate authority and jurisdiction;</li> <li>issue and requested function;</li> <li>records and protected annex transmitted;</li> <li>basis for competence;</li> <li>response-duty source and effect: <code>legal</code>, <code>contractual</code>, <code>charter_internal</code>, <code>voluntary_commitment</code>, <code>advisory</code>, or <code>none</code>;</li> <li>acknowledgment-clock source and decision-clock source;</li> <li><code>GMEAIA-07</code> response-time assessment reference where applicable;</li> <li>response state: <code>offered</code>, <code>acknowledged</code>, <code>accepted</code>, <code>partially_accepted</code>, <code>capacity_limited</code>, <code>refused</code>, <code>deferred</code>, <code>referred</code>, <code>timed_out</code>, <code>misrouted</code>, <code>constitutional_gap</code>, <code>returned</code>, or <code>closed</code>;</li> <li>reasons, conflicts, missing prerequisites, and expected harm during delay;</li> <li>provisional-safe-state record reference, which cannot be activated by referral alone;</li> <li>post-acceptance action-clock and review references;</li> <li>sender duty, recipient duty, custody, escalation, and jurisdictional or capacity status;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Referral, receipt, notification, silence, delay, or schema compatibility does not create acceptance, correctness, or transfer of authority.</li></ul> <p><strong>Lifecycle relation:</strong> Must reach explicit acceptance before recipient action; unresolved, refused, and timed-out states retain named custody and escalation.</p> <h2>GMEAIA-09 — Affected Persons, Communities, Nations, Outsiders, and Transboundary Effects Map</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Identifies who bears benefits, burdens, risks, data exposure, exclusion, or irreversible effects.</p> <p><strong>Required content:</strong></p> <ul><li>directly affected persons and groups;</li> <li>residents, users, workers, tenants, migrants, minorities, and dissenters;</li> <li>affected Indigenous nations;</li> <li>neighbouring and downstream communities;</li> <li>future and non-human interests where applicable;</li> <li>affected outsiders and non-members;</li> <li>burdens transferred and resources accompanying them;</li> <li>representation gaps, internal plurality, notice, participation, support, and remedy needs;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A majority, host institution, platform, geographic label, or community leadership cannot erase internal minorities or affected outsiders.</li></ul> <p><strong>Lifecycle relation:</strong> Required before consent, trial authorization, scaling, responsibility transfer, or institutional redesign.</p> <h2>GMEAIA-10 — Affected Indigenous Nation, Applicable Indigenous Law, and Protected-Knowledge Authority</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Records the specific affected nation or nations and their own authority, law, representatives, and knowledge controls.</p> <p><strong>Required content:</strong></p> <ul><li>nation or people as self-identified;</li> <li>territorial, relational, and subject-matter connection;</li> <li>recognized representatives and internal plurality;</li> <li>applicable Indigenous law and consent route;</li> <li>non-engagement, refusal, and withdrawal;</li> <li>sacred or restricted knowledge controls;</li> <li>benefit sharing and non-transfer;</li> <li>complaint and correction route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A global Indigenous representative, retired framework, external elder, quota, facilitator, or advisory council cannot consent or speak for an affected nation.</li></ul> <p><strong>Lifecycle relation:</strong> Controls affected-nation participation and protected knowledge across the lifecycle.</p> <h2>GMEAIA-11 — Notice, Accessibility, Independent Advice, and Participation Support</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Ensures participation is informed, accessible, materially possible, and not dependent on adopting the proposed method.</p> <p><strong>Required content:</strong></p> <ul><li>notice content and languages;</li> <li>accessible, offline, oral, assisted, and disability formats;</li> <li>time and location;</li> <li>independent legal, technical, cultural, or financial advice;</li> <li>care, transport, connectivity, income, and safety support;</li> <li>anti-retaliation and anonymity options;</li> <li>records access and correction;</li> <li>non-participation and alternative routes;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Lack of digital access, literacy, identity documents, money, certified facilitators, or agreement with GGF methods cannot reduce standing.</li></ul> <p><strong>Lifecycle relation:</strong> Required for consequential consent, deliberation, review, and remedy.</p> <h2>GMEAIA-12 — Proposal Intake, Source Signal, Sponsor, and Status Record</h2> <p><strong>Action class:</strong> <code>A03</code><br> <strong>Purpose:</strong> Records a proposed response without implying endorsement or authority.</p> <p><strong>Required content:</strong></p> <ul><li>proposal identity and sponsor;</li> <li>source signals and evidence;</li> <li>problem definition;</li> <li>intended beneficiaries and affected parties;</li> <li>requested authority and resources;</li> <li>status and normative force;</li> <li>conflicts and funding interests;</li> <li>withdrawal and correction route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A proposal, algorithmic recommendation, community petition, facilitator recommendation, or council agenda item is not consent or authorization.</li></ul> <p><strong>Lifecycle relation:</strong> Opens proposal development and deliberation.</p> <h2>GMEAIA-13 — Proposal Objective, Alternatives, Rights Effects, Causal Mechanism, and Reversibility Record</h2> <p><strong>Action class:</strong> <code>A03</code><br> <strong>Purpose:</strong> Makes the substantive choice, causal theory, and alternatives reviewable before method or authority decisions.</p> <p><strong>Required content:</strong></p> <ul><li>objectives, theory of change, and success conditions;</li> <li>causal mechanism and variables controlled by the proposer;</li> <li>action and non-action alternatives;</li> <li>rights and essential-service effects;</li> <li>distribution of benefits and burdens;</li> <li>minimum causally adequate scope;</li> <li>reversibility, rollback, and stranded commitments;</li> <li>resource, staffing, technology, and upstream dependencies;</li> <li>known unknowns, failure modes, and conclusions the proposal cannot establish;</li> <li>duration, review, exit, narrowing, and non-scaling conditions;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A good objective, reversible design, or small pilot does not supply authority or prove that the experiment can test the mechanism it claims.</li></ul> <p><strong>Lifecycle relation:</strong> Required before deliberation and trial authorization.</p> <h2>GMEAIA-14 — Method Selection, Cultural Adaptation, Autonomy Statement, and Authority Effect</h2> <p><strong>Action class:</strong> <code>A04</code><br> <strong>Purpose:</strong> Records why a deliberative, assessment, technical, or implementation method was chosen and adapted.</p> <p><strong>Required content:</strong></p> <ul><li>method and version;</li> <li>decision owner and participants;</li> <li>selection rationale and alternatives;</li> <li>community-chosen adaptations;</li> <li>self-identification and internal plurality;</li> <li>authority-effect label;</li> <li>known biases, exclusions, and administrative burden;</li> <li>review, fork, and abandonment route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Cultural adaptation cannot classify a community from outside, essentialize identity, or authorize acts beyond the adopting authority.</li></ul> <p><strong>Lifecycle relation:</strong> Links selected methods to their bounded purpose.</p> <h2>GMEAIA-15 — Deliberation Plan, Facilitation Mandate, Record, Dissent, and Reasons</h2> <p><strong>Action class:</strong> <code>A04</code><br> <strong>Purpose:</strong> Defines how a proposal will be deliberated and how facilitation remains subordinate to lawful decision authority.</p> <p><strong>Required content:</strong></p> <ul><li>decision authority and question;</li> <li>participant and constituency map;</li> <li>facilitator mandate and conflicts;</li> <li>evidence and knowledge modes;</li> <li>agenda, speaking, accessibility, and safety rules;</li> <li>dissent and minority-report process;</li> <li>decision rule and reasons;</li> <li>recording, confidentiality, and correction;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Facilitators, ethics panels, epistemic assessors, algorithms, or ceremonies cannot replace the decision authority.</li></ul> <p><strong>Lifecycle relation:</strong> Produces a reasoned deliberative record, not authorization by itself.</p> <h2>GMEAIA-16 — Epistemic Readiness, Provenance, Common-Mode Dependence, Disinformation, and Trust Assessment</h2> <p><strong>Action class:</strong> <code>A12</code><br> <strong>Purpose:</strong> Advises whether the information environment can support a decision and whether apparent plurality shares one failure substrate.</p> <p><strong>Required content:</strong></p> <ul><li>assessment authority, method, and independence;</li> <li>claims and evidence reviewed;</li> <li>provenance and source diversity;</li> <li>missing, inaccessible, or protected knowledge;</li> <li>shared data, AI, infrastructure, funders, methods, and professional networks;</li> <li>common-mode failure and fallback channels;</li> <li>disinformation exposure, language, accessibility, trust, and power conditions;</li> <li>uncertainty, dissent, recommended repairs, residual correlation risk, and non-veto status;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A threshold, score, certification failure, or correlation finding cannot suspend a lawful decision or create an emergency exception.</li></ul> <p><strong>Lifecycle relation:</strong> The competent decision body records how it responds and who accepts residual correlation risk.</p> <h2>GMEAIA-17 — Ethics, Harm, Rights, and Anti-Capture Advisory Review</h2> <p><strong>Action class:</strong> <code>A12</code><br> <strong>Purpose:</strong> Surfaces ethical risks, rights impacts, capture, conflicts, and missing safeguards without becoming hidden approval power.</p> <p><strong>Required content:</strong></p> <ul><li>review body and competence;</li> <li>ethical sources and plural foundations;</li> <li>affected-party and rights analysis;</li> <li>capture, conflict, and objective-reproduction analysis;</li> <li>protected knowledge and non-transfer;</li> <li>foreseeable harms and alternatives;</li> <li>recommendations and dissent;</li> <li>advisory status and response requirement;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>An ethics gate, MOS alignment, Indigenous-framework representative, or certified reviewer cannot create or withhold legal authority.</li></ul> <p><strong>Lifecycle relation:</strong> Must be answered with reasons where the governing charter requires review.</p> <h2>GMEAIA-18 — Consent Requirement, Holder, Scope, and Dependency Map</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Determines which forms of consent, authorization, consultation, notice, assent, or collective decision are required.</p> <p><strong>Required content:</strong></p> <ul><li>proposed action and affected interests;</li> <li>consent or decision holders;</li> <li>legal or customary basis;</li> <li>individual, collective, fiduciary, parental, worker, member, or affected-nation form;</li> <li>scope and duration;</li> <li>dependencies and sequencing;</li> <li>capacity, representation, and internal dissent;</li> <li>refusal, withdrawal, and remedy;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Consent cannot create jurisdiction over third parties or waive non-derogable rights; one consent holder cannot waive another’s rights.</li></ul> <p><strong>Lifecycle relation:</strong> Precedes collection of consent and trial authorization.</p> <h2>GMEAIA-19 — Consent, Refusal, Withdrawal, and Non-Retaliation Record</h2> <p><strong>Action class:</strong> <code>A05</code><br> <strong>Purpose:</strong> Records a decision by a valid holder without reducing it to a free-text field.</p> <p><strong>Required content:</strong></p> <ul><li>holder and verified capacity;</li> <li>information received;</li> <li>decision and scope;</li> <li>conditions and reservations;</li> <li>time, duration, and review;</li> <li>withdrawal process;</li> <li>internal dissent and minority protection;</li> <li>non-retaliation and consequences of refusal;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Silence, attendance, use of a service, receipt of support, technical signature, or absence of objection is not consent unless valid law expressly establishes it with safeguards.</li></ul> <p><strong>Lifecycle relation:</strong> Must remain linked to the exact proposal and may require renewal.</p> <h2>GMEAIA-20 — Authority Verification, Causal Responsibility, Decision Class, and Protected-Domain Classification</h2> <p><strong>Action class:</strong> <code>A06</code><br> <strong>Purpose:</strong> Confirms authority and maps whether responsibility, resources, and control over causal variables are aligned.</p> <p><strong>Required content:</strong></p> <ul><li>authority record and exact jurisdiction;</li> <li>authority formation: <code>retained</code>, <code>delegated</code>, <code>transferred</code>, <code>concurrent</code>, <code>jointly_constituted</code>, or <code>absent</code>;</li> <li>for <code>jointly_constituted</code>: constituting parties, shared governance object, affected non-parties, source, exit, and surviving duties;</li> <li>decision class and consequence;</li> <li>principal causal variables;</li> <li>legal and practical controller of each variable;</li> <li>affected parties and their participation, consent, challenge, and remedy standing; burdens assigned and resources transferred, without inferring responsibility from affected status;</li> <li>upstream and external dependencies and continuing duties;</li> <li>shared, concurrent, or absent jurisdiction;</li> <li>impossible mandate or impossible pilot condition;</li> <li>protected-domain screening and applicable interfaces;</li> <li>verification result, constitutional-gap flag, and unresolved limits;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Method simplicity, local popularity, reversibility, urgency, or the local appearance of consequences cannot establish authority or causal responsibility.</li></ul> <p><strong>Lifecycle relation:</strong> Fail-closed gate before trial authorization and required for consequential transfer, devolution, compact formation, jointly constituted authority, reform mandate, or system-effect pilot.</p> <h2>GMEAIA-21 — Trial Authorization, Conditions, Scope, and Non-Precedent Record</h2> <p><strong>Action class:</strong> <code>A07</code><br> <strong>Purpose:</strong> Authorizes a bounded experiment without converting it into permanent policy or broader precedent.</p> <p><strong>Required content:</strong></p> <ul><li>competent authority and exact power;</li> <li>proposal and consent records;</li> <li>participants, territory, services, and assets;</li> <li>duration and activation window;</li> <li>conditions, exclusions, and essential minimums;</li> <li>monitoring, review, rollback, and remedy;</li> <li>funding and operator;</li> <li>non-precedent and no-silent-scaling clause;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A trial authorization does not authorize coercive execution, expansion to nonparticipants, new jurisdictions, permanent enactment, or use outside its conditions.</li></ul> <p><strong>Lifecycle relation:</strong> Required for consequential experiments.</p> <h2>GMEAIA-22 — Adoption Claim, Deliberative Acceptance, and Registration Record</h2> <p><strong>Action class:</strong> <code>A07</code><br> <strong>Purpose:</strong> Records that an entity claims to adopt or accept a proposal and states the legal meaning of that claim.</p> <p><strong>Required content:</strong></p> <ul><li>adopting entity and representation;</li> <li>proposal and version;</li> <li>decision process and reasons;</li> <li>authority-effect status;</li> <li>consent and authority references;</li> <li>trial or permanent character;</li> <li>unresolved conditions;</li> <li>registration, correction, and challenge;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>An adopt() event without complete authority references means only that adoption was claimed; it is not binding or active.</li></ul> <p><strong>Lifecycle relation:</strong> May precede or follow trial authorization depending on local law, but cannot replace it.</p> <h2>GMEAIA-23 — Operational Activation, Start Conditions, Operator, and Clock Record</h2> <p><strong>Action class:</strong> <code>A08</code><br> <strong>Purpose:</strong> Distinctly starts an authorized action and begins legal, operational, review, and expiry clocks.</p> <p><strong>Required content:</strong></p> <ul><li>authorization and adoption records;</li> <li>activation authority;</li> <li>operator and accountable lead;</li> <li>preconditions satisfied;</li> <li>start time and territory;</li> <li>resources released;</li> <li>monitoring and incident channels;</li> <li>review, expiry, stop, rollback, and response clocks;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Authorization, registration, smart-contract creation, software deployment, or funding approval does not equal activation unless this record is valid.</li></ul> <p><strong>Lifecycle relation:</strong> Makes the action operational.</p> <h2>GMEAIA-24 — Implementation Plan, Responsibilities, Dependencies, Service Boundaries, and Handoff Clocks</h2> <p><strong>Action class:</strong> <code>A08</code><br> <strong>Purpose:</strong> Translates authorization into accountable tasks without expanding scope or losing responsibility between actors.</p> <p><strong>Required content:</strong></p> <ul><li>work packages and responsible actors;</li> <li>affected persons and participation;</li> <li>dependencies, handoffs, acknowledgment clocks, and decision clocks;</li> <li>budgets, procurement, and administrative burden;</li> <li>data and technology;</li> <li>essential-service and safety boundaries;</li> <li>maintenance, ordinary owner, and support-withdrawal plan;</li> <li>incident, complaint, change control, escalation, completion, and closure conditions;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>An implementer cannot reinterpret broad goals as new powers, treat operational convenience as amendment, or leave a failed handoff without named custody.</li></ul> <p><strong>Lifecycle relation:</strong> Controls day-to-day implementation.</p> <h2>GMEAIA-25 — Non-Derogable Rights, Essential Services, Safety, and Continuing Duties Record</h2> <p><strong>Action class:</strong> <code>A08</code><br> <strong>Purpose:</strong> Protects rights and duties that cannot be experimented away or allowed to expire by default.</p> <p><strong>Required content:</strong></p> <ul><li>applicable rights and safeguards;</li> <li>essential water, food, shelter, health, income, disability, education, safety, and communication duties;</li> <li>child and dependent-person protection;</li> <li>worker and pension obligations;</li> <li>environmental and restoration duties;</li> <li>evidence and records preservation;</li> <li>continuity arrangements;</li> <li>monitoring and remedy;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A sunset, funding withdrawal, failed metric, community vote, or operator exit cannot terminate continuing duties.</li></ul> <p><strong>Lifecycle relation:</strong> Must be linked to every trial or institutional transition that could affect protected interests.</p> <h2>GMEAIA-26 — Funding Authority, Participation Support, Independence, and Non-Conformity Record</h2> <p><strong>Action class:</strong> <code>A14</code><br> <strong>Purpose:</strong> Separates lawful funding from pressure to accept a method, ideology, institutional redesign, or data exposure.</p> <p><strong>Required content:</strong></p> <ul><li>funding source and authority;</li> <li>purpose, amount, recipient, and custodian;</li> <li>eligibility and evidence;</li> <li>participation support independent of substantive agreement;</li> <li>conditions and prohibited conditions;</li> <li>worker, beneficiary, essential-function, and support-withdrawal continuity;</li> <li>notice, review, appeal, and correction;</li> <li>expiry, recovery, and unused funds;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A readiness score, ethics alignment, module count, public reputation, or method adoption cannot automatically create, deny, freeze, or claw back funding.</li></ul> <p><strong>Lifecycle relation:</strong> Required before money or material support becomes consequential.</p> <h2>GMEAIA-27 — Procurement, Contract, Vendor, Platform, and Technical-Service Record</h2> <p><strong>Action class:</strong> <code>A14</code><br> <strong>Purpose:</strong> Makes private and technical implementation relationships visible and bounded.</p> <p><strong>Required content:</strong></p> <ul><li>procuring authority and process;</li> <li>vendor and beneficial ownership;</li> <li>service, deliverables, and authority effect;</li> <li>data, security, and intellectual property;</li> <li>subcontractors and conflicts;</li> <li>performance and audit;</li> <li>termination, continuity, migration, and local maintenance;</li> <li>liability, remedy, and records return;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A vendor, platform, smart contract, cloud service, or algorithm cannot become the decision authority or withhold public records and services through lock-in.</li></ul> <p><strong>Lifecycle relation:</strong> Controls outsourced implementation.</p> <h2>GMEAIA-28 — Data Purpose, Lawful Basis, Access Class, Retention, Publication, and Withdrawal</h2> <p><strong>Action class:</strong> <code>A16</code><br> <strong>Purpose:</strong> Defines how governance data are collected, used, linked, published, corrected, and disposed.</p> <p><strong>Required content:</strong></p> <ul><li>data categories and subjects;</li> <li>purpose and lawful basis;</li> <li>minimum necessary fields;</li> <li>access class and recipients;</li> <li>protected knowledge and source restrictions;</li> <li>retention and deletion;</li> <li>publication and anonymization;</li> <li>correction, withdrawal, breach, and remedy;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Public-by-default, transparency, content addressing, blockchain, or learning goals cannot override confidentiality, protected knowledge, safety, correction, or lawful deletion.</li></ul> <p><strong>Lifecycle relation:</strong> Required for all digital and analog records.</p> <h2>GMEAIA-29 — AI, Sensor, Model, Algorithm, and Automation Role Record</h2> <p><strong>Action class:</strong> <code>A16</code><br> <strong>Purpose:</strong> Defines what automated systems may observe, recommend, route, or execute and what decisions are prohibited.</p> <p><strong>Required content:</strong></p> <ul><li>system identity, version, operator, and purpose;</li> <li>training or calibration sources;</li> <li>inputs, outputs, and confidence;</li> <li>human accountable reviewer;</li> <li>bias, security, and failure analysis;</li> <li>shared-model and provider dependencies;</li> <li>prohibited decisions and protected domains;</li> <li>logging, challenge, correction, shutdown, retention, and vendor exit;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>AI and sensors cannot provide consent, establish representation, declare an emergency, determine jurisdiction, authorize adoption, activate powers, adjudicate, sanction, or renew authority.</li></ul> <p><strong>Lifecycle relation:</strong> Required before automated assistance is used.</p> <h2>GMEAIA-30 — Monitoring Plan, Baseline, Metric, Counterfactual, Burden, and Review Schedule</h2> <p><strong>Action class:</strong> <code>A09</code><br> <strong>Purpose:</strong> Defines what will be observed and how success or harm will be assessed without making metrics self-executing.</p> <p><strong>Required content:</strong></p> <ul><li>objectives and baseline;</li> <li>metrics and qualitative evidence;</li> <li>counterfactual and comparison, including simpler or non-GGF alternatives where feasible;</li> <li>methods, uncertainty, and gaming risks;</li> <li>distributional, rights, latency, and administrative-burden indicators;</li> <li>data responsibilities;</li> <li>review schedule and thresholds for human review;</li> <li>correction, retirement, and framework-hypothesis references;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A threshold, dashboard, score, sentiment analysis, reputation change, or KPI cannot automatically scale, suspend, fund, punish, dissolve, or renew an action.</li></ul> <p><strong>Lifecycle relation:</strong> Begins with activation and supports later review.</p> <h2>GMEAIA-31 — Outcome Observation, Incident, Side Effect, and Distributional Impact Record</h2> <p><strong>Action class:</strong> <code>A09</code><br> <strong>Purpose:</strong> Captures what occurred, including unintended effects and unequal burdens.</p> <p><strong>Required content:</strong></p> <ul><li>time and scope;</li> <li>outcomes and incidents;</li> <li>affected-party reports;</li> <li>rights and essential-service effects;</li> <li>distributional impacts;</li> <li>operator and external factors;</li> <li>data quality and dissent;</li> <li>urgent referrals and correction;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Observed correlation or public sentiment does not establish causation, success, failure, breach, or legitimacy.</li></ul> <p><strong>Lifecycle relation:</strong> Feeds causal assessment and review.</p> <h2>GMEAIA-32 — Causal Assessment, Contribution, External Shock, Causal Adequacy, and Uncertainty Record</h2> <p><strong>Action class:</strong> <code>A09</code><br> <strong>Purpose:</strong> Separates measured change from a reasoned account of what caused it and whether the intervention was capable of testing the claimed mechanism.</p> <p><strong>Required content:</strong></p> <ul><li>question and assessor;</li> <li>methods and evidence;</li> <li>counterfactual;</li> <li>causal mechanism and variables controlled;</li> <li>alternative causes, upstream conditions, and external shocks;</li> <li>pilot boundary and mechanisms excluded;</li> <li>contribution, attribution, and minimum causal adequacy;</li> <li>uncertainty, dissent, limits on use, review, and correction;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A successful outcome does not prove the method caused it; a poor outcome does not prove misconduct; an underpowered pilot cannot establish system effectiveness.</li></ul> <p><strong>Lifecycle relation:</strong> Supports review, learning, remedy, and scaling limits.</p> <h2>GMEAIA-33 — Midpoint Review, Corrective Action, and Continued-Operation Decision</h2> <p><strong>Action class:</strong> <code>A09</code><br> <strong>Purpose:</strong> Determines whether an active trial continues unchanged, changes, pauses, or terminates.</p> <p><strong>Required content:</strong></p> <ul><li>review authority and independence;</li> <li>records reviewed;</li> <li>affected-party evidence;</li> <li>rights, safety, and service status;</li> <li>metric, causal, latency, and burden assessment;</li> <li>conditions and corrective actions;</li> <li>decision, reasons, and dissent;</li> <li>next review and challenge;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>The original adopter or operator cannot unilaterally certify success where conflicts require independent review.</li></ul> <p><strong>Lifecycle relation:</strong> May trigger amendment, pause, remedy, or continued operation.</p> <h2>GMEAIA-34 — Complaint, Challenge, Interim Relief, Appeal, and Independent Review</h2> <p><strong>Action class:</strong> <code>A09</code><br> <strong>Purpose:</strong> Provides an effective route to contest signals, scores, methods, consent, authority, implementation, publication, delay, omission, or harm.</p> <p><strong>Required content:</strong></p> <ul><li>complainant and standing;</li> <li>challenged action or omission and requested relief;</li> <li>notice and evidence access;</li> <li>independent reviewer;</li> <li>interim relief and anti-retaliation;</li> <li>decision and reasons;</li> <li>appeal or reconsideration;</li> <li>remedy and correction propagation;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A complaint route is not effective if the challenged facilitator, funder, platform, adopter, operator, or non-responsive authority controls the outcome.</li></ul> <p><strong>Lifecycle relation:</strong> Available throughout the lifecycle.</p> <h2>GMEAIA-35 — Amendment, Scope Change, Version Change, and New-Risk Assessment</h2> <p><strong>Action class:</strong> <code>A10</code><br> <strong>Purpose:</strong> Prevents operational changes from silently expanding authority.</p> <p><strong>Required content:</strong></p> <ul><li>current authorization and version;</li> <li>proposed change and rationale;</li> <li>materiality assessment;</li> <li>new affected parties, risks, data, jurisdictions, or causal assumptions;</li> <li>renewed consent and authority needs;</li> <li>technical and budget changes;</li> <li>approval and effective date;</li> <li>rollback and supersession;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Feature updates, local adaptation, rule-engine changes, vendor updates, or successful practice cannot amend authority by deployment.</li></ul> <p><strong>Lifecycle relation:</strong> Required for material changes.</p> <h2>GMEAIA-36 — Pause, Suspension, Stop, Rollback, and Safe-State Record</h2> <p><strong>Action class:</strong> <code>A10</code><br> <strong>Purpose:</strong> Records temporary or protective cessation and restoration of a safe baseline.</p> <p><strong>Required content:</strong></p> <ul><li>trigger and authority;</li> <li>scope and start;</li> <li>safety and service continuity;</li> <li>data and asset custody;</li> <li>operator duties;</li> <li>review and maximum duration;</li> <li>rollback target;</li> <li>resumption or termination conditions;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A technical kill switch, facilitator request, metric threshold, or funder notice cannot suspend lawful rights or services without authority.</li></ul> <p><strong>Lifecycle relation:</strong> Used for incidents, consent withdrawal, failed preconditions, or review.</p> <h2>GMEAIA-37 — Renewal, Reauthorization, and Active Re-Consent Record</h2> <p><strong>Action class:</strong> <code>A10</code><br> <strong>Purpose:</strong> Requires active justification before temporary authority continues.</p> <p><strong>Required content:</strong></p> <ul><li>expiring action and authority;</li> <li>performance, latency, dependency, and harm review;</li> <li>remaining need and alternatives;</li> <li>affected-party and consent update;</li> <li>jurisdiction and law update;</li> <li>conditions and amendments;</li> <li>new duration and clocks;</li> <li>decision, dissent, challenge, and non-renewal effects;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Silence, inertia, continuing software operation, unused sunset logic, or absence of complaint is not renewal.</li></ul> <p><strong>Lifecycle relation:</strong> Required before expiry where continuation is sought.</p> <h2>GMEAIA-38 — Expiry, Automatic Deactivation, and Continuing-Duty Transition Record</h2> <p><strong>Action class:</strong> <code>A11</code><br> <strong>Purpose:</strong> Records the legal and operational effects of reaching an expiry condition.</p> <p><strong>Required content:</strong></p> <ul><li>expired authority and time;</li> <li>automatic deactivation steps;</li> <li>services and duties that continue;</li> <li>open cases and claims;</li> <li>data and asset custody;</li> <li>operator access revocation;</li> <li>temporary successor if needed;</li> <li>notice and review;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Expiry does not erase harms, debts, pensions, records duties, restoration, child protection, or essential-service obligations.</li></ul> <p><strong>Lifecycle relation:</strong> Begins closure unless renewed.</p> <h2>GMEAIA-39 — Termination, Closure, Authority Return, Asset Return, and Succession Record</h2> <p><strong>Action class:</strong> <code>A11</code><br> <strong>Purpose:</strong> Completes the end of an action or institution and returns power to its lawful source.</p> <p><strong>Required content:</strong></p> <ul><li>termination authority and basis;</li> <li>effective time;</li> <li>operators and access removed;</li> <li>assets, funds, licences, and infrastructure returned or transferred;</li> <li>staff, beneficiaries, and service continuity;</li> <li>records and data disposition;</li> <li>unresolved duties and successor;</li> <li>final reasons, audit, challenge, and material closure feasibility;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A celebratory sunset, dashboard status, archive entry, software deletion, or formal exit without a viable continuity route is not complete closure.</li></ul> <p><strong>Lifecycle relation:</strong> Required for complete lifecycle conformance.</p> <h2>GMEAIA-40 — Learning Artifact, Failure Library, Story Bank, and Public Memory Record</h2> <p><strong>Action class:</strong> <code>A16</code><br> <strong>Purpose:</strong> Permits learning without converting participation into permanent exposure.</p> <p><strong>Required content:</strong></p> <ul><li>source action and purpose;</li> <li>content and factual review;</li> <li>consent for identifiable material;</li> <li>anonymization and residual risk;</li> <li>protected and excluded content;</li> <li>access and reuse licence;</li> <li>withdrawal, correction, and expiry;</li> <li>responsible publisher, sample-selection limits, and remedy;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Consent to a pilot, employment, funding, facilitation, or testimony is not consent to permanent public storytelling; a learning library is not a representative sample by default.</li></ul> <p><strong>Lifecycle relation:</strong> Produces a bounded learning resource.</p> <h2>GMEAIA-41 — Record Correction, Retraction, Supersession, and Dependency Propagation</h2> <p><strong>Action class:</strong> <code>A11</code><br> <strong>Purpose:</strong> Corrects governance records and every dependent decision without pretending immutable systems cannot change.</p> <p><strong>Required content:</strong></p> <ul><li>record and error;</li> <li>correcting authority;</li> <li>corrected content and reason;</li> <li>affected persons and decisions;</li> <li>dependency graph and propagation;</li> <li>public and protected notices;</li> <li>interim relief;</li> <li>archive and audit trail;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Append-only storage may preserve history but cannot preserve an error as the current authoritative state.</li></ul> <p><strong>Lifecycle relation:</strong> Required when signals, identities, scores, consent, authority, outcomes, or handoff states are wrong.</p> <h2>GMEAIA-42 — Harm, Remedy, Restitution, Compensation, Rehabilitation, and Non-Repetition Record</h2> <p><strong>Action class:</strong> <code>A11</code><br> <strong>Purpose:</strong> Records repair for wrongful or harmful implementation.</p> <p><strong>Required content:</strong></p> <ul><li>harm and affected parties;</li> <li>causal and legal basis;</li> <li>urgent support;</li> <li>restoration or restitution;</li> <li>financial compensation;</li> <li>record and reputation correction;</li> <li>institutional, incentive, or technical change;</li> <li>monitoring, closure, and appeal;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Ending a pilot or apologizing does not discharge remedy.</li></ul> <p><strong>Lifecycle relation:</strong> May survive termination until complete.</p> <h2>GMEAIA-43 — Scaling Recommendation, Transferability Limits, Transition Readiness, and Evidence Package</h2> <p><strong>Action class:</strong> <code>A10</code><br> <strong>Purpose:</strong> Converts pilot learning into a bounded recommendation and tests whether a useful function can become ordinary, durable provision.</p> <p><strong>Required content:</strong></p> <ul><li>source trial and context;</li> <li>evidence, causal adequacy, and uncertainty;</li> <li>necessary conditions and contexts not tested;</li> <li>failed and excluded contexts;</li> <li>rights and distributional effects;</li> <li>ordinary owner, budget, staffing, maintenance, and support-withdrawal durability;</li> <li>recommended scope and alternatives;</li> <li>non-authority status and reasons for remaining temporary;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Success, reputation, funding tier, adoption count, benchmark attainment, or continued pilot activity cannot scale an action or prove transition readiness.</li></ul> <p><strong>Lifecycle relation:</strong> May be submitted to a new competent authority.</p> <h2>GMEAIA-44 — Scaling, Replication, New-Jurisdiction, and Permanent-Enactment Authorization</h2> <p><strong>Action class:</strong> <code>A10</code><br> <strong>Purpose:</strong> Authorizes a new instance, jurisdiction, population, or permanent rule through its own lawful process.</p> <p><strong>Required content:</strong></p> <ul><li>new authority and jurisdiction;</li> <li>proposal and scaling recommendation;</li> <li>new affected-party map;</li> <li>local law and consent;</li> <li>adaptation and alternatives;</li> <li>funding, operator, data, maintenance, and ordinary ownership;</li> <li>review, sunset or permanent amendment route;</li> <li>reasons and challenge;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A template, network effect, treaty aspiration, successful pilot, or cross-platform compatibility cannot create this authorization.</li></ul> <p><strong>Lifecycle relation:</strong> Creates a new bounded authority chain, not an extension by inference.</p> <h2>GMEAIA-45 — Institutional Purpose, Mandate, Power, Selection Pressure, and Obsolescence Audit</h2> <p><strong>Action class:</strong> <code>A15</code><br> <strong>Purpose:</strong> Assesses whether an institution or programme still serves its lawful mandate and what selection pressures reproduce its revealed behavior.</p> <p><strong>Required content:</strong></p> <ul><li>charter and mandate;</li> <li>auditor and independence;</li> <li>beneficiaries and affected parties;</li> <li>performance, harms, and alternatives;</li> <li>power and capture analysis;</li> <li>budget, appointment, promotion, removal, prestige, blame, survival, and continuation incentives;</li> <li>incentives of auditors, facilitators, funders, vendors, and reform bodies;</li> <li>behavior likely to regenerate after reform and pressures the proposal changes;</li> <li>essential and unresolved functions;</li> <li>options: retain, reform, transfer, merge, narrow, or close; advisory status, dissent, and response;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A scorecard, AI diagnostic, trust score, audit finding, or stated reform commitment cannot amend or dissolve an institution or prove that its operative objective changed.</li></ul> <p><strong>Lifecycle relation:</strong> Feeds charter review, incentive reform, authority reform, or closure authorization.</p> <h2>GMEAIA-46 — Charter Amendment, Governance Redesign, Constituency, and Decision-Rights Record</h2> <p><strong>Action class:</strong> <code>A15</code><br> <strong>Purpose:</strong> Constitutes lawful institutional redesign, including councils, voting shares, vetoes, representation, and response duties.</p> <p><strong>Required content:</strong></p> <ul><li>charter-amendment authority and procedure;</li> <li>proposed bodies and powers;</li> <li>constituencies and selection;</li> <li>mandates, conflicts, removal, accountability, and duty-to-respond;</li> <li>rights and minority safeguards;</li> <li>affected Indigenous nation authority;</li> <li>transition and legal continuity;</li> <li>approval, entry into force, review, and challenge;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A governance blueprint, facilitator recommendation, fixed percentage, youth or future-generation label, or toolkit adoption cannot amend a charter.</li></ul> <p><strong>Lifecycle relation:</strong> Required before governance redesign becomes operative.</p> <h2>GMEAIA-47 — Institutional Funding Eligibility, Condition, Incentive, and Appeal Record</h2> <p><strong>Action class:</strong> <code>A14</code><br> <strong>Purpose:</strong> Separates institutional finance from coercive reform leverage and exposes continuation incentives.</p> <p><strong>Required content:</strong></p> <ul><li>funding authority and programme;</li> <li>eligibility criteria and evidence;</li> <li>condition and relation to mandate;</li> <li>essential-function and beneficiary impact;</li> <li>worker and pension safeguards;</li> <li>independence from method or ideology conformity;</li> <li>continuation, closure, and dependency incentives;</li> <li>decision, reasons, duration, appeal, correction, and transition support;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Module counts, readiness or regeneration tiers, public pressure, or GGF alignment cannot automatically grant voting rights, freeze funds, or force charter change.</li></ul> <p><strong>Lifecycle relation:</strong> Controls funding tied to institutional transition.</p> <h2>GMEAIA-48 — Institutional Transition, Worker, Beneficiary, Contract, and Service Continuity Record</h2> <p><strong>Action class:</strong> <code>A15</code><br> <strong>Purpose:</strong> Protects people and obligations during reform, merger, transfer, or downsizing.</p> <p><strong>Required content:</strong></p> <ul><li>transition authority and plan;</li> <li>workers, unions, pensions, and benefits;</li> <li>beneficiaries and essential functions;</li> <li>contracts, grants, and pending cases;</li> <li>assets, debts, and licences;</li> <li>data, archives, and confidentiality;</li> <li>successor and contingency;</li> <li>notice, participation, remedy, review, and unresolved-duty custody;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Institutional agility does not erase labour, pension, beneficiary, contractual, or public-service duties.</li></ul> <p><strong>Lifecycle relation:</strong> Required before material organizational transition.</p> <h2>GMEAIA-49 — Institutional Dissolution, Successor, Dark Archive, and Unresolved-Duty Custody</h2> <p><strong>Action class:</strong> <code>A15</code><br> <strong>Purpose:</strong> Closes an institution or programme through lawful authority and custodianship.</p> <p><strong>Required content:</strong></p> <ul><li>dissolution authority and legal basis;</li> <li>effective date and scope;</li> <li>successor institutions;</li> <li>staff and beneficiary arrangements;</li> <li>assets, liabilities, and restricted funds;</li> <li>records, archives, access, and deletion;</li> <li>pending claims, duties, and cases;</li> <li>final audit, remedy, challenge, and reopening route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A purpose audit, sunset date, funding loss, hostile leadership, public score, or Dark Archive deposit cannot itself dissolve an institution.</li></ul> <p><strong>Lifecycle relation:</strong> Completes institutional closure.</p> <h2>GMEAIA-50 — Facilitator Qualification, Appointment, Mandate, Conflict, Complaint, and Removal</h2> <p><strong>Action class:</strong> <code>A13</code><br> <strong>Purpose:</strong> Makes facilitators accountable without creating a professional monopoly.</p> <p><strong>Required content:</strong></p> <ul><li>qualification and local-equivalence route;</li> <li>appointing body and participant choice;</li> <li>mandate and prohibited acts;</li> <li>cultural and trauma competence;</li> <li>conflicts, funding, and recusal;</li> <li>complaint, replacement, and removal;</li> <li>liability and insurance where relevant;</li> <li>duration, record custody, and dependency-reduction duty;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Certification does not create decision authority; lack of certification cannot exclude locally trusted competence or block urgent access to participation.</li></ul> <p><strong>Lifecycle relation:</strong> Required for consequential facilitated processes.</p> <h2>GMEAIA-51 — Auditor, Assessor, Ethics Reviewer, and Epistemic Reviewer Independence and Common-Mode Record</h2> <p><strong>Action class:</strong> <code>A13</code><br> <strong>Purpose:</strong> Defines competence and independence across funding, data, methods, infrastructure, and professional networks.</p> <p><strong>Required content:</strong></p> <ul><li>reviewer identity and mandate;</li> <li>selection and qualification;</li> <li>funding and beneficial interests;</li> <li>conflicts and recusal;</li> <li>method and evidence access;</li> <li>shared data, AI, vendors, infrastructure, appointment authorities, professional networks, and ontologies;</li> <li>independent channel, fallback, minority reports, and residual correlation risk;</li> <li>publication, protected annex, complaint, correction, and removal;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Organizational separation does not establish independence where reviewers share the same funder, data, model, platform, method, or professional incentive.</li></ul> <p><strong>Lifecycle relation:</strong> Required for consequential audits, gates, and common-mode stress tests.</p> <h2>GMEAIA-52 — Catalyst Team, Liaison, Evolution Cell, and Technical-Assistance Mandate</h2> <p><strong>Action class:</strong> <code>A13</code><br> <strong>Purpose:</strong> Bounds support actors embedded in communities or institutions and exposes their curation and continuation incentives.</p> <p><strong>Required content:</strong></p> <ul><li>host invitation and appointing authority;</li> <li>purpose and tasks;</li> <li>no-command and no-representation limits;</li> <li>access to people, systems, and records;</li> <li>funding, conflicts, tool-curation influence, and continuation incentives;</li> <li>staff and community protections;</li> <li>duration, exit, handover, local capacity transfer, and conditions making support unnecessary;</li> <li>complaints, liability, learning, and independent review;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Support, expertise, embedded presence, emergency context, host dependency, repository stewardship, or compatibility knowledge does not create authority to govern the host.</li></ul> <p><strong>Lifecycle relation:</strong> Required before external implementation support begins.</p> <h2>GMEAIA-53 — Framework, Tool Core, Fork, Schema, Compatibility, Version, Deprecation, and Stewardship Record</h2> <p><strong>Action class:</strong> <code>A16</code><br> <strong>Purpose:</strong> Keeps modular tools adaptable without invisible central control, unsafe divergence, or compatibility becoming shadow governance.</p> <p><strong>Required content:</strong></p> <ul><li>tool and schema identity;</li> <li>normative core versus optional profile;</li> <li>steward and change process;</li> <li>compatibility promises and exact technical necessity;</li> <li>effects of incompatibility on funding, support, recognition, and participation;</li> <li>fork rights and labels;</li> <li>security, migration support, deprecation, rollback, and expiry;</li> <li>framework theory of change, disconfirming evidence, narrowing, suspension, and replacement conditions;</li> <li>dispute, correction, and archive;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>The central steward cannot make local legal decisions through a software update; incompatibility does not establish illegitimacy; a fork cannot claim compatibility while omitting constitutional fields.</li></ul> <p><strong>Lifecycle relation:</strong> Required for EGP profiles, framework releases, and tool libraries.</p> <h2>GMEAIA-54 — Offline, Oral, Paper, Assisted, and Low-Tech Record Equivalence</h2> <p><strong>Action class:</strong> <code>A16</code><br> <strong>Purpose:</strong> Provides equal dignity and effect to non-digital participation and records.</p> <p><strong>Required content:</strong></p> <ul><li>record form and custodian;</li> <li>witnessing or attestation;</li> <li>translation and accessibility;</li> <li>identity and representation checks;</li> <li>digitization without alteration;</li> <li>confidentiality and protected knowledge;</li> <li>correction and duplicate resolution;</li> <li>service, timing, influence, and remedy parity;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Digital signatures, blockchain, app access, or machine readability cannot be prerequisites for standing, service, consent, challenge, or remedy.</li></ul> <p><strong>Lifecycle relation:</strong> Required wherever digital systems are offered.</p> <h2>GMEAIA-55 — Emergency Signal, CDEE Referral, Mission Acceptance, and ECRC Interface</h2> <p><strong>Action class:</strong> <code>A17</code><br> <strong>Purpose:</strong> Routes urgent matters into the harmonized emergency architecture without allowing implementation tools to declare or command emergencies.</p> <p><strong>Required content:</strong></p> <ul><li>source signal and validation;</li> <li>CDEE event identity;</li> <li>candidate emergency authority;</li> <li>declaration or acceptance record;</li> <li>mission and information scope;</li> <li>command and operational roles;</li> <li>clocks, review, termination, and return;</li> <li>data, finance, remedy, unresolved risk, and non-response escalation;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A crisis stack, 72-hour kit, urgent score, PIS notification, facilitator, AI alert, or community adoption cannot declare an emergency.</li></ul> <p><strong>Lifecycle relation:</strong> Required before emergency powers or cross-domain missions activate.</p> <h2>GMEAIA-56 — Protected-Domain Experiment Exception and Specialized-Interface Authorization</h2> <p><strong>Action class:</strong> <code>A17</code><br> <strong>Purpose:</strong> Allows carefully bounded pilots in protected domains only through the controlling constitutional interface. The protected-domain catalogue in §2.1 is normative and may be extended by the controlling domain interface.</p> <p><strong>Required content:</strong></p> <ul><li>protected domain and risk;</li> <li>controlling framework and interface;</li> <li>specialized authority and safeguards;</li> <li>participants and exclusions;</li> <li>essential minimums and non-derogation;</li> <li>independent monitoring and stop authority;</li> <li>duration, rollback, and remedy;</li> <li>public reasons and protected annex;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Ordinary trial authorization cannot cover detention, policing, essential-service deprivation, migration status, title transfer, irreversible ecology, high-risk technology, adjudication, or emergency command.</li></ul> <p><strong>Lifecycle relation:</strong> Required in addition to GMEAIA-21.</p> <h2>GMEAIA-57 — Coercive or Enforcement Request, Acceptance, Execution, and SCPA Handoff</h2> <p><strong>Action class:</strong> <code>A17</code><br> <strong>Purpose:</strong> Separates implementation and review from compulsory execution.</p> <p><strong>Required content:</strong></p> <ul><li>underlying decision and enforceable order;</li> <li>requested action class;</li> <li>SCPA authority records;</li> <li>recipient acceptance;</li> <li>individualized scope and safeguards;</li> <li>operator, command, and use limits;</li> <li>review, incident, and evidence records;</li> <li>termination, remedy, return, and referral-only status for non-coercive frameworks;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>An adopter, facilitator, funder, community, smart contract, platform, ethics reviewer, implementation team, or general cross-framework handoff cannot search, seize, detain, restrain, freeze, sanction, or use force through this specification.</li></ul> <p><strong>Lifecycle relation:</strong> Required for coercive execution; non-coercive frameworks may refer but cannot accept or execute the coercive function.</p> <h2>GMEAIA-58 — Non-Activation, Sandbox, Prototype, Simulation, and Demonstration Register</h2> <p><strong>Action class:</strong> <code>A18</code><br> <strong>Purpose:</strong> Marks environments and records that must not be mistaken for live authority.</p> <p><strong>Required content:</strong></p> <ul><li>sandbox or prototype identity;</li> <li>owner and purpose;</li> <li>synthetic versus real data;</li> <li>excluded powers and protected domains;</li> <li>technical and organizational isolation;</li> <li>display and API warnings;</li> <li>test users and consent;</li> <li>termination, deletion, and incident route;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>A successful demonstration, smart contract, simulation, digital twin, mock council, pilot BAZ, or test credential cannot affect real rights, services, funds, or authority.</li></ul> <p><strong>Lifecycle relation:</strong> Required for all non-production deployments.</p> <h2>GMEAIA-59 — Cross-Framework Handoff, Conformance, Recipient Response, Acceptance, and Custody Record</h2> <p><strong>Action class:</strong> <code>A18</code><br> <strong>Purpose:</strong> Makes interoperability explicit and prevents missing authority, non-response, or refusal from disappearing between frameworks.</p> <p><strong>Required content:</strong></p> <ul><li>source and destination frameworks and versions;</li> <li>source records and action class;</li> <li>requested function;</li> <li>controlling interface;</li> <li>authority and protected-data package;</li> <li>response-duty source and effect: <code>legal</code>, <code>contractual</code>, <code>charter_internal</code>, <code>voluntary_commitment</code>, <code>advisory</code>, or <code>none</code>;</li> <li>acknowledgment-clock source and decision-clock source;</li> <li><code>GMEAIA-07</code> response-time assessment reference where applicable;</li> <li>response state: <code>offered</code>, <code>acknowledged</code>, <code>accepted</code>, <code>partially_accepted</code>, <code>capacity_limited</code>, <code>refused</code>, <code>deferred</code>, <code>referred</code>, <code>timed_out</code>, <code>misrouted</code>, <code>constitutional_gap</code>, <code>returned</code>, or <code>closed</code>;</li> <li>reasons, conflicts, missing prerequisites, and alternative recipient;</li> <li>provisional-safe-state record reference, which cannot be activated by handoff alone;</li> <li>post-acceptance action-clock and review references;</li> <li>sender and recipient duties, custody, escalation, return, closure, and unresolved state;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Schema compatibility, API receipt, event subscription, shared terminology, or silence does not mean legal acceptance or duty discharge.</li></ul> <p><strong>Lifecycle relation:</strong> Required for consequential cross-framework transport.</p> <h2>GMEAIA-60 — Data Return, Deletion, Archive, Access Revocation, and Protected-Memory Disposition</h2> <p><strong>Action class:</strong> <code>A11</code><br> <strong>Purpose:</strong> Completes the information lifecycle after withdrawal, expiry, closure, correction, or dissolution.</p> <p><strong>Required content:</strong></p> <ul><li>record classes and custodians;</li> <li>retention duties and legal holds;</li> <li>return and portability;</li> <li>deletion, crypto-shredding, or sealed archive;</li> <li>protected Indigenous and community knowledge;</li> <li>public-memory justification;</li> <li>access revocation and key destruction;</li> <li>verification, complaints, and unresolved obligations;</li></ul> <p><strong>Prohibited inference:</strong></p> <ul><li>Immutability, public transparency, research value, or failure-learning interest cannot justify indefinite access to protected or unlawfully held data.</li></ul> <p><strong>Lifecycle relation:</strong> Required to complete withdrawal, expiry, correction, closure, or dissolution.</p> <hr> <h1>9. Conformance gates</h1> <p>A deployment claiming <code>GMEAIA/0.2.1</code> conformance shall satisfy all applicable gates.</p> <table><thead><tr><th>Gate</th><th>Requirement</th></tr></thead><tbody><tr><td>G01</td><td>Exact authority effect, normative force, status, source, version, and accountable actor are recorded.</td></tr><tr><td>G02</td><td>No method, score, funding decision, signature, software function, or compatibility claim creates authority by implication.</td></tr><tr><td>G03</td><td>Consequence profile CP0–CP3 is selected and justified.</td></tr><tr><td>G04</td><td>Record burden and accessible or low-tech equivalence are proportionate.</td></tr><tr><td>G05</td><td>Affected parties, outsiders, internal minorities, and affected Indigenous nations are mapped.</td></tr><tr><td>G06</td><td>Consent, authority, authorization, adoption, activation, and execution remain distinct.</td></tr><tr><td>G07</td><td>Causal variables, legal and practical controllers, transferred burdens, resources, and upstream duties are identified where material.</td></tr><tr><td>G08</td><td>Impossible mandate, impossible pilot, and constitutional-gap conditions remain available states.</td></tr><tr><td>G09</td><td>Response clocks, acceptance, refusal, deferment, timeout, escalation, and custody are explicit for consequential handoffs.</td></tr><tr><td>G10</td><td>Non-response does not create automatic authority transfer or erase continuing responsibility.</td></tr><tr><td>G11</td><td>Observation and review channels disclose common-mode dependencies and fallback.</td></tr><tr><td>G12</td><td>Objective-reproduction analysis is completed for long-lived or systemically central institutions and support ecosystems.</td></tr><tr><td>G13</td><td>Protected domains use specialized interfaces and fail closed.</td></tr><tr><td>G14</td><td>Rights, essential services, workers, beneficiaries, records, and unresolved duties survive expiry and closure.</td></tr><tr><td>G15</td><td>AI, vendors, funders, facilitators, auditors, and Catalyst actors remain bounded and challengeable.</td></tr><tr><td>G16</td><td>Metrics, alerts, and findings trigger review rather than self-executing constitutional consequences.</td></tr><tr><td>G17</td><td>Pilots are small enough for safety and large enough to expose the claimed mechanism.</td></tr><tr><td>G18</td><td>Scaling evidence addresses external validity, ordinary ownership, maintenance, and support-withdrawal durability.</td></tr><tr><td>G19</td><td>Tool and framework compatibility cannot become practical legitimacy or ideological conformity by implication.</td></tr><tr><td>G20</td><td>Every operational framework and every long-lived, systemically central, or self-renewing mechanism states disconfirming evidence and narrowing, suspension, replacement, or non-scaling conditions.</td></tr><tr><td>G21</td><td>Corrections propagate to dependent records and decisions.</td></tr><tr><td>G22</td><td>Closure returns authority, assets, access, data, and unresolved-duty custody.</td></tr></tbody></table> <hr> <h1>10. Compound tests added in the v0.2 series</h1> <table><thead><tr><th>Test</th><th>Scenario</th><th>Required outcome</th></tr></thead><tbody><tr><td>T01</td><td>A local body receives responsibility for a condition caused by an upstream authority</td><td>Causal Responsibility Profile identifies the upstream controller and continuing duty; local administration does not prove local responsibility.</td></tr><tr><td>T02</td><td>A competent authority ignores a consequential referral</td><td>Handoff enters <code>timed_out</code>; sender custody, expected harm, escalation, and unresolved duties remain visible; no automatic transfer occurs.</td></tr><tr><td>T03</td><td>No institution has jurisdiction over an integrated condition</td><td>Status becomes <code>constitutional_gap</code>; the interface routes a constituting process and does not invent a residual sovereign.</td></tr><tr><td>T04</td><td>Three independent panels use the same AI, data vendor, and funder</td><td>They are recorded as correlated; common-mode stress test and fallback are required.</td></tr><tr><td>T05</td><td>A voluntary workshop is required to complete a full CP3 record bundle</td><td>Non-conformant over-administration; CP0 or CP1 applies.</td></tr><tr><td>T06</td><td>A technically simple pilot affects household water access</td><td>CP3 protected-domain route applies despite technical simplicity.</td></tr><tr><td>T07</td><td>A pilot tests acceptability but is presented as proof of system effectiveness</td><td>Rejected; causal adequacy and conclusion limits must be stated.</td></tr><tr><td>T08</td><td>A successful pilot has no ordinary owner, budget, maintenance, or staff after grant expiry</td><td>Scaling recommendation remains incomplete.</td></tr><tr><td>T09</td><td>A Catalyst Team controls tool visibility, training, and funding assistance</td><td>GMEAIA-52 records curation power, incentives, local-capacity transfer, and conditions for exit.</td></tr><tr><td>T10</td><td>An institution completes a purpose audit but promotion, budget, and appointment incentives remain unchanged</td><td>Audit cannot claim reproductive reform without evidence that selection pressures changed.</td></tr><tr><td>T11</td><td>A framework passes every schema check but adds delay and produces no improved outcome</td><td>Conformance remains valid; effectiveness claim fails and framework narrowing review begins.</td></tr><tr><td>T12</td><td>A fork is labelled incompatible and loses all practical access to support</td><td>GMEAIA-53 requires a technical necessity, proportional effects, migration route, and no legitimacy inference.</td></tr><tr><td>T13</td><td>A receiver refuses a handoff because prerequisites are missing</td><td>Refusal is reasoned, custody remains explicit, and an alternative route or escalation is recorded.</td></tr><tr><td>T14</td><td>A legal exit exists but essential service and platform alternatives do not</td><td>Closure or exit cannot be represented as materially complete.</td></tr><tr><td>T15</td><td>A dashboard target is met after the system changes the metric definition</td><td>Independent outcomes and data-change governance prevent self-validation.</td></tr><tr><td>T16</td><td>A high-consequence framework has no condition under which it would narrow or stop</td><td>Framework-level conformance fails G20.</td></tr></tbody></table> <hr> <h1>Appendix A — Forty-eight-field common header</h1> <table><thead><tr><th align="right">No.</th><th>Field</th></tr></thead><tbody><tr><td align="right"><code>01</code></td><td><code>record_id</code></td></tr><tr><td align="right"><code>02</code></td><td><code>record_type</code></td></tr><tr><td align="right"><code>03</code></td><td><code>schema_version</code></td></tr><tr><td align="right"><code>04</code></td><td><code>created_at</code></td></tr><tr><td align="right"><code>05</code></td><td><code>effective_at</code></td></tr><tr><td align="right"><code>06</code></td><td><code>expires_at</code></td></tr><tr><td align="right"><code>07</code></td><td><code>status</code></td></tr><tr><td align="right"><code>08</code></td><td><code>normative_force</code></td></tr><tr><td align="right"><code>09</code></td><td><code>authority_effect</code></td></tr><tr><td align="right"><code>10</code></td><td><code>action_class</code></td></tr><tr><td align="right"><code>11</code></td><td><code>source_framework_id</code></td></tr><tr><td align="right"><code>12</code></td><td><code>source_framework_version</code></td></tr><tr><td align="right"><code>13</code></td><td><code>source_record_ids</code></td></tr><tr><td align="right"><code>14</code></td><td><code>supersedes</code></td></tr><tr><td align="right"><code>15</code></td><td><code>superseded_by</code></td></tr><tr><td align="right"><code>16</code></td><td><code>actor_id</code></td></tr><tr><td align="right"><code>17</code></td><td><code>actor_type</code></td></tr><tr><td align="right"><code>18</code></td><td><code>office_or_role</code></td></tr><tr><td align="right"><code>19</code></td><td><code>representation_source</code></td></tr><tr><td align="right"><code>20</code></td><td><code>technical_credential_refs</code></td></tr><tr><td align="right"><code>21</code></td><td><code>constituting_instrument</code></td></tr><tr><td align="right"><code>22</code></td><td><code>legal_power</code></td></tr><tr><td align="right"><code>23</code></td><td><code>jurisdiction_territorial</code></td></tr><tr><td align="right"><code>24</code></td><td><code>jurisdiction_personal</code></td></tr><tr><td align="right"><code>25</code></td><td><code>jurisdiction_subject_matter</code></td></tr><tr><td align="right"><code>26</code></td><td><code>jurisdiction_temporal</code></td></tr><tr><td align="right"><code>27</code></td><td><code>affected_party_refs</code></td></tr><tr><td align="right"><code>28</code></td><td><code>affected_indigenous_nation_refs</code></td></tr><tr><td align="right"><code>29</code></td><td><code>protected_domain_flags</code></td></tr><tr><td align="right"><code>30</code></td><td><code>consent_record_refs</code></td></tr><tr><td align="right"><code>31</code></td><td><code>authority_record_refs</code></td></tr><tr><td align="right"><code>32</code></td><td><code>activation_record_refs</code></td></tr><tr><td align="right"><code>33</code></td><td><code>access_class</code></td></tr><tr><td align="right"><code>34</code></td><td><code>public_summary</code></td></tr><tr><td align="right"><code>35</code></td><td><code>protected_annex_refs</code></td></tr><tr><td align="right"><code>36</code></td><td><code>data_purpose</code></td></tr><tr><td align="right"><code>37</code></td><td><code>retention_rule</code></td></tr><tr><td align="right"><code>38</code></td><td><code>correction_status</code></td></tr><tr><td align="right"><code>39</code></td><td><code>challenge_status</code></td></tr><tr><td align="right"><code>40</code></td><td><code>review_due_at</code></td></tr><tr><td align="right"><code>41</code></td><td><code>closure_state</code></td></tr><tr><td align="right"><code>42</code></td><td><code>unresolved_duty_refs</code></td></tr><tr><td align="right"><code>43</code></td><td><code>handoff_state</code></td></tr><tr><td align="right"><code>44</code></td><td><code>recipient_refs</code></td></tr><tr><td align="right"><code>45</code></td><td><code>recipient_acceptance_refs</code></td></tr><tr><td align="right"><code>46</code></td><td><code>hashes_and_signatures</code></td></tr><tr><td align="right"><code>47</code></td><td><code>human_accountable_officer</code></td></tr><tr><td align="right"><code>48</code></td><td><code>prohibited_inferences</code></td></tr></tbody></table> <p>The common header remains intentionally stable. Record-specific fields carry causal responsibility, response clocks, common-mode dependencies, objective-reproduction analysis, proportionality, and falsification.</p> <hr> <h1>Appendix B — Shared primitive mapping</h1> <table><thead><tr><th>Shared primitive</th><th>Primary GMEAIA records</th><th>Supporting records</th></tr></thead><tbody><tr><td>Causal Responsibility Profile</td><td><code>20</code></td><td><code>07</code>, <code>09</code>, <code>13</code>, <code>24</code>, <code>32</code>, <code>42</code>, <code>45</code></td></tr><tr><td>Response, Refusal, and Omission</td><td><code>08</code>, <code>59</code></td><td><code>07</code>, <code>23</code>, <code>24</code>, <code>34</code>, <code>55</code>, <code>57</code></td></tr><tr><td>Independence and Objective-Reproduction Review</td><td><code>16</code>, <code>45</code>, <code>51</code>, <code>52</code></td><td><code>17</code>, <code>26</code>, <code>27</code>, <code>29</code>, <code>40</code>, <code>47</code>, <code>53</code></td></tr><tr><td>Proportionality and Falsification</td><td>consequence profiles; <code>53</code></td><td><code>02</code>, <code>13</code>, <code>20</code>, <code>30</code>, <code>32</code>, <code>43</code>, <code>58</code></td></tr></tbody></table> <hr> <h1>Appendix C — Default response fields</h1> <p>These are the canonical operational fields. Constitutional documents should preserve the information but defer exact states and lifecycle semantics to GMEAIA.</p> <p><strong>Source request:</strong><br> <strong>Candidate duty-holder:</strong><br> <strong>Basis for competence:</strong><br> <strong>Response-duty source:</strong><br> <strong>Response-duty effect:</strong> <code>legal</code> / <code>contractual</code> / <code>charter_internal</code> / <code>voluntary_commitment</code> / <code>advisory</code> / <code>none</code><br> <strong>Acknowledgment-clock source:</strong><br> <strong>Acknowledgment due:</strong><br> <strong>Decision-clock source:</strong><br> <strong>Decision due:</strong><br> <strong>GMEAIA-07 response-time assessment reference:</strong><br> <strong>State:</strong> <code>offered</code> / <code>acknowledged</code> / <code>accepted</code> / <code>partially_accepted</code> / <code>capacity_limited</code> / <code>refused</code> / <code>deferred</code> / <code>referred</code> / <code>timed_out</code> / <code>misrouted</code> / <code>constitutional_gap</code> / <code>returned</code> / <code>closed</code><br> <strong>Reasons and evidence:</strong><br> <strong>Conflicts:</strong><br> <strong>Missing prerequisites:</strong><br> <strong>Expected harm during delay:</strong><br> <strong>Provisional-safe-state record reference:</strong><br> <strong>Post-acceptance action clock:</strong><br> <strong>Sender duty retained:</strong><br> <strong>Recipient duty accepted:</strong><br> <strong>Escalation:</strong><br> <strong>Unresolved-duty custody:</strong><br> <strong>Closure:</strong></p> <hr> <h1>Appendix D — Default framework falsification fields</h1> <p>This profile applies to frameworks and to long-lived, systemically central, or self-renewing mechanisms. Independence review, objective-reproduction review, and framework falsification are separately triggerable even where one human-readable form combines them.</p> <p><strong>Framework or long-lived mechanism:</strong><br> <strong>Theory of change:</strong><br> <strong>Expected mechanism:</strong><br> <strong>Architecture-added latency:</strong><br> <strong>Administrative burden:</strong><br> <strong>Common-mode dependencies:</strong><br> <strong>Disconfirming evidence:</strong><br> <strong>Narrowing condition:</strong><br> <strong>Suspension condition:</strong><br> <strong>Replacement or deprecation condition:</strong><br> <strong>Non-scaling condition:</strong><br> <strong>Review authority and date:</strong></p> <hr> <h1>Conclusion</h1> <p><code>GMEAIA/0.2.1</code> preserves the central achievement of v0.1: methods, pilots, funding, technology, and coordination cannot counterfeit authority.</p> <p>It adds the mirror requirement revealed by the recursive audit:</p> <blockquote><p><strong>A constitutionally bounded system must also show who controls the causes, who must respond, what happens when they do not, which dependencies can fail together, which incentives reproduce institutional behavior, and what evidence would show that the framework itself should become smaller or end.</strong></p></blockquote> <p>The specification therefore remains a lifecycle grammar rather than a governance sovereign. It makes responsibility traceable without assigning it by implication.</p>',1);function f(e){var t=a();o(1184),n(e,t)}export{f as default,r as metadata};
